  var MOTIFS = [mFlag, mEll, mHook, mTri, mBoot, mZig];
  // موتیف‌های «حرف‌نما» — دست‌داریِ بسیار خوانا (مثلِ حرف در آینه). بدونِ تقارنِ چرخشی.
